function _deepMatch(obj, criteria) {
  return Object.entries(criteria).every(([key, value]) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return obj[key] && typeof obj[key] === 'object' && _deepMatch(obj[key], value)
    }

    return obj[key] === value
  })
}

function _containsKeyOrValue(obj, target) {
  if (obj === target) return true

  if (obj && typeof obj === 'object') {
    return Object.entries(obj).some(([key, value]) => {
      // match key
      if (key === target) return true

      // match value
      if (value === target) return true

      // recurse into nested objects
      return _containsKeyOrValue(value, target)
    })
  }

  return false
}

function _findIndexes(arr, criteria) {
  return arr.reduce((indexes, item, index) => {
    const match =
      criteria && typeof criteria === 'object' && !Array.isArray(criteria)
        ? _deepMatch(item, criteria)
        : _containsKeyOrValue(item, criteria)

    if (match) {
      indexes.push(index)
    }

    return indexes
  }, [])
}
function universalSort(array, key = null, order = 'asc') {
  const isAsc = order.toLowerCase() === 'asc';

  return [...array].sort((a, b) => {
    // Extract values if sorting by object key
    let valA = key !== null && typeof a === 'object' && a !== null ? a[key] : a;
    let valB = key !== null && typeof b === 'object' && b !== null ? b[key] : b;

    // Handle undefined or null values (push to bottom)
    if (valA === undefined || valA === null) return 1;
    if (valB === undefined || valB === null) return -1;

    // Compare Numbers
    if (typeof valA === 'number' && typeof valB === 'number') {
      return isAsc ? valA - valB : valB - valA;
    }

    // Compare Strings (case-insensitive, handles numeric strings correctly)
    const strA = String(valA);
    const strB = String(valB);
    return isAsc
      ? strA.localeCompare(strB, undefined, { numeric: true, sensitivity: 'base' })
      : strB.localeCompare(strA, undefined, { numeric: true, sensitivity: 'base' });
  });
}
