function toParticleY(input) {
  if (typeof input === 'number') return 0 - input;
  if (Array.isArray(input)) return input.map(y => 0 - y);
  if (typeof input === 'object' && input !== null) {
    const result = { ...input };
    if (input.min !== undefined && input.max !== undefined) {
      result.min = 0 - input.max;
      result.max = 0 - input.min;
    }
    return result;
  }
  return input;
}

function toParticleSpeedY(input) {
  if (typeof input === 'number') return -input;
  if (Array.isArray(input)) return input.map(v => -v);
  if (typeof input === 'object' && input !== null) {
    const result = { ...input };
    if (input.min !== undefined && input.max !== undefined) {
      result.min = -input.max;
      result.max = -input.min;
    }
    return result;
  }
  return input;
}
async function cloneEffects(isRun, config, toPhaser) {
  if (isRun) {
    try {
      let newConf = JSON.parse(JSON.stringify(config))
      if (newConf.index == undefined) {
        newConf.index = 0
      }
      if (newConf.y != undefined) {
        newConf.y= toParticleY(newConf.y)
      }
      if (newConf.speedY != undefined) {
        newConf.speedY=toParticleSpeedY(newConf.speedY)
      }
      if (newConf.accelerationY != undefined) {
        newConf.accelerationY=toParticleSpeedY(newConf.accelerationY)
      }
      if (typeof newConf.gravityY == 'number') {
        newConf.gravityY = -newConf.gravityY
      }
      if (typeof newConf.deathZoneY == 'number') {
        newConf.deathZoneY = -newConf.deathZoneY
      }

      toPhaser(true, 'particles_add', newConf)
    } catch (error) {}
  }
}
async function fetch_api(API){
  try {
      if (API.indexOf("navigator.")==0){
          return JSON.parse(JSON.stringify(navigator[API.replace("navigator.","")]))
      }else if (API.indexOf("http")==0){
          const response = await fetch(API);
          return JSON.parse(JSON.stringify(await response.json()))
      }else{
          return API
      }
  } catch (e) {
      console.log(e)
      return {}
  }
}
function encodeBase64(str) {
  if (str){
    return btoa(
      encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, (_, p1) => String.fromCharCode('0x' + p1)),
    )
  }else{
    return ""
  }
}
function decodeBase64(str) {
  if (str){
    return decodeURIComponent(
      Array.prototype.map
        .call(atob(str), (c) => '%' + c.charCodeAt(0).toString(16).padStart(2, '0'))
        .join(''),
    )
  }else{
    return ""
  }
}
async function server_readPJFile(which) {
  return new Promise(async (resolve) => {
    let rtn=''
    try {
      let response = await fetch(___goServer+'/api/player/'+which+'?pid='+___phaserOnly_pid);
      rtn=await response.json()
      if (rtn.err==0){
        if (rtn.file==''){
            ___fileAccess[which]=rtn.time
            resolve ({err:0,data:""})
        }else{
          let json=JSON.parse(decodeBase64(rtn.file))
          if (json.key=='JS,you knew.'){
            rtn.file=json.data
            ___fileAccess[which]=rtn.time
            resolve ({err:0,data:JSON.parse(json.data)})
          }else{
            resolve ({err:0,data:rtn.file})
          }
        }
      }else{
        resolve ({err:rtn.err,data:''})
      }
    } catch {
     if (rtn.file){
      resolve ({err:0,data:rtn.file})
     }else{
      resolve ({err:1,data:''})
     }
    }
  })
}
async function readPJFile(which){
  if (___phaserOnly_mode){
    return await server_readPJFile(which)
  }else{
    try {
      ___fileAccess[which] = new Date().getTime()
      let data = localStorage.getItem('file_'+___createID1+'_'+which)
      if (data == null) {
        return { err: 0, data: '' }
      } else {
        return { err: 0, data: JSON.parse(data).data }
      }
    } catch {
      return { err: 0, data: '' }
    }
  }
}

async function server_writePJFile(which,data) {
  return new Promise(async (resolve) => {
    let send = {
      data: data,
      key: "not secure at all, it's well know"
    }
    try{
      let eData = encodeBase64(JSON.stringify(send))
      let rsp= await fetch(___goServer+'/api/player/'+which+'write?pid='+___phaserOnly_pid, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ data: eData ,time:___fileAccess[which] })
          })
      let rtn=await rsp.json()
      resolve ({err:rtn.err})
    } catch {
      resolve ({err:1})
    }
  })
}
async function writePJFile(which,data){
  if (___phaserOnly_mode){
    return await server_writePJFile(which,data)
  }else{
    try {
      if (___fileAccess[which]) {
        let lsData = localStorage.getItem('file_'+___createID1+'_'+which)
        if (lsData != null) {
          let jData = JSON.parse(lsData)
          if (___fileAccess[which] < jData.writeTime) {
            return { err: 2 }
          }
        }
        ___fileAccess[which] = new Date().getTime()
        let jData = {
          data: data,
          writeTime: ___fileAccess[which],
        }
        localStorage.setItem('file_'+___createID1+'_'+which,  JSON.stringify(jData))
        return { err: 0 }
      } else {
        return { err: 3 }
      }
    } catch {
      ___fileAccess[which] = new Date().getTime()
      localStorage.removeItem('file_'+___createID1+'_'+which)
      return { err: 4 }
    }
  }
}
function getJSONValue(theJSON, keyStr) {
  let code = {}
  try {
    if (keyStr == null || keyStr == undefined || keyStr == '') {
      code = false
    } else if (theJSON != null && theJSON != undefined && theJSON != '') {
      let valueList = keyStr.split('.')
      if (valueList.length == 1) {
        code = theJSON[keyStr]
      } else {
        code = theJSON
        for (let eachOne of valueList) {
          if (eachOne != '') {
            if (code[eachOne] == undefined) {
              code = false
              break
            }
            code = code[eachOne]
          }
        }
      }
    }
  } catch (e) {
      console.log(e);
  }
  if (code == undefined) {
    code = false
  }
  return code
}
function deleteJSONValue(theJSON, keyStr) {
    try {
        if (keyStr == null || keyStr == undefined || keyStr == '') {
        theJSON={}
        } else if (theJSON != null && theJSON != undefined && theJSON != '') {
        let valueList = keyStr.split('.')
        if (valueList.length == 1) {
            delete  theJSON[keyStr]
        } else {
           let code = theJSON
            let preCode=null,delKey=""
            for (let eachOne of valueList) {
            if (eachOne != '') {
                if (code[eachOne] == undefined) {
                code = {}
                break
                }
                preCode=code
                delKey=eachOne
                code = code[eachOne]
            }
            }
            if (preCode){
                delete preCode[delKey]
            }
        }
        }
    } catch (e) {
        console.log(e);
    }
}
